{"code": "import fsspec, datetime
fs = fsspec.filesystem('onedata')
base = 'icsa2027_data_20261101T090944Z/s1z'

# Walk year by year via glob per year to avoid pagination caps
years = {}
all_names = []
for y in range(1980, 2027):
    try:
        fl = fs.glob(f'{base}/sst_{y}*.nc')
    except Exception as e:
        fl = []
    if fl:
        names = sorted(f.rsplit('/',1)[1] for f in fl)
        years[y] = (names[0], names[-1], len(names))
        all_names.extend(names)
print('years with files:', min(years), '-', max(years), '| total files:', len(all_names))
for y in sorted(years):
    print(y, years[y])

# check gaps in expected daily coverage between min and max date
import datetime as dt
d0 = dt.date(1982,1,1); d1 = dt.date(int(max(years) and all_names[-1][4:8]), int(all_names[-1][8:10]), int(all_names[-1][10:12]))
print('range:', d0, d1, 'expected days:', (d1-d0).days+1)
have = {n[4:14] for n in all_names}
missing = []
d = d0
while d <= d1:
    if d.strftime('%Y%m%d') not in have:
        missing.append(str(d))
    d += dt.timedelta(days=1)
print('missing count:', len(missing))
print('missing sample:', missing[:20])
"}

