{"code": "import fsspec, datetime as dt
fs = fsspec.filesystem('onedata')
base = 'icsa2027_data_20261101T090944Z/s1z'

# find last existing date: probe monthly 1sts in 2024-2026
for y in [2024, 2025, 2026]:
    for m in range(1, 13):
        p = f'{base}/sst_{y}{m:02d}01.nc'
        if fs.exists(p):
            print('exists:', p)
    # also probe year end
    if fs.exists(f'{base}/sst_{y}1231.nc'):
        print('exists:', y, '1231')

print('---')
# find the last day of the last month that exists
found_last = None
for y in [2024, 2025, 2026]:
    for m in range(12, 0, -1):
        for d in range(31, 0, -1):
            try:
                dd = dt.date(y, m, d)
            except ValueError:
                continue
            p = f'{base}/sst_{y}{m:02d}{d:02d}.nc'
            if fs.exists(p):
                found_last = dd
                break
        if found_last: break
    if found_last: break
print('last date probe:', found_last)
