{"code": "import os, time, datetime as dt
from concurrent.futures import ThreadPoolExecutor
import fsspec, numpy as np

print('cwd:', os.getcwd())
try:
    import netCDF4; print('netCDF4', netCDF4.__version__)
except Exception as e:
    print('no netCDF4:', e)

fs = fsspec.filesystem('onedata')
base = 'icsa2027_data_20261101T090944Z/s1z'
os.makedirs('/work/nc', exist_ok=True)

# test threaded download: 60 files
dates = [dt.date(2021,6,d) for d in range(1,32)] + [dt.date(2021,7,d) for d in range(1,30)]
def fetch(d):
    lp = f'/work/nc/sst_{d:%Y%m%d}.nc'
    if os.path.exists(lp) and os.path.getsize(lp) > 0:
        return d, True, 'cached'
    try:
        fs.get(f'{base}/sst_{d:%Y%m%d}.nc', lp)
        return d, os.path.exists(lp) and os.path.getsize(lp) > 0, ''
    except Exception as e:
        return d, False, repr(e)

t0 = time.time()
with ThreadPoolExecutor(8) as ex:
    res = list(ex.map(fetch, dates))
dt_, ok, errs = time.time()-t0, sum(1 for r in res if r[1]), [r for r in res if not r[1]]
print(f'60 files in {dt_:.1f}s -> {60/dt_:.1f} files/s; ok={ok}; errs={len(errs)}')
if errs: print(errs[:5])
"}

